cret"]}, {"id": "mists-velvet-petals", "label": "Velvet Petals", "price": 70.9, "images": ["/catalog/mists/velvet-petals.webp"], "description": "Body Mist Velvet Petals. Feminina e inesperada. Um deleite irresistível para os sentidos.", "specs": ["Tipo de fragrância: Frutal Gourmand", "Notas de topo: Carambola brilhante, glacê de amêndoas doces", "Notas de coração: Leite de coco, flor de damasco açucarada", "Notas de fundo: Almíscares aconchegantes, sândalo cremoso", "Volume: 250 ml", "100% original Victoria’s Secret"]}, {"id": "mists-velvet-petals-2", "label": "Velvet Petals (2)", "price": 70.9, "images": ["/catalog/mists/velvet-petals-2.webp"], "description": "Body Mist Velvet Petals (2). Feminina e inesperada. Um deleite irresistível para os sentidos.", "specs": ["Tipo de fragrância: Frutal Gourmand", "Notas de topo: Carambola brilhante, glacê de amêndoas doces", "Notas de coração: Leite de coco, flor de damasco açucarada", "Notas de fundo: Almíscares aconchegantes, sândalo cremoso", "Volume: 250 ml", "100% original Victoria’s Secret"]}, {"id": "mists-vanilla-lace", "label": "Vanilla Lace", "price": 70.9, "images": ["/catalog/mists/vanilla-lace.webp"], "description": "Body Mist Vanilla Lace. Suave e doce para sempre. Dos arquivos. Uma onda de calor cremoso.", "specs": ["Tipo de fragrância: Gourmand", "Notas de topo: Orquídea de baunilha, café com leite", "Notas de coração: Hortênsia rosa, pétalas de lírio-do-vale", "Notas de fundo: Baunilha cremosa, sândalo", "Volume: 250 ml", "100% original Victoria’s Secret"]}, {"id": "mists-golden-apricot-honey", "label": "Golden Apricot & Honey", "price": 70.9, "images": ["/catalog/mists/golden-apricot-honey.webp"], "description": "Body Mist Golden Apricot & Honey. Aroma: frutado, doce e quente. Notas: damasco dourado e mel. Sensação: radiante, suave e envolvente. Estilo: doce, elegante e quente.", "specs": ["Tipo de fragrância: Frutado, doce e quente", "Notas: Damasco dourado e mel", "100% original Victoria’s Secret"]}, {"id